local config = {
  ui_story_31380401_1_dialog_content = "Hari yang indah.",
  ui_story_31380401_2_dialog_content = "Tidak ada Eclipsite atau tugas yang rumit.",
  ui_story_31380401_3_dialog_content = "Ini waktu yang tepat untuk tidur siang di kamar.",
  ui_story_31380401_4_dialog_content = "Ini juga waktu yang tepat untuk olahraga di luar ruangan.",
  ui_story_31380401_5_dialog_content = "Hai, Siobhan.",
  ui_story_31380401_X5_dialog_content = "Oh, PlayerName, Vice, halo!",
  ui_story_31380401_X6_dialog_content = "Kalian sedang membicarakan apa?",
  ui_story_31380401_6_dialog_content = "Kami sedang membahas tempat untuk bersantai. Ada saran?",
  ui_story_31380401_7_dialog_content = "Bersantai...? Hmm... Kupikir kafe adalah tempat yang tepat.",
  ui_story_31380401_8_dialog_content = "Keseimbangan kehidupan kerja penting untuk mempertahankan efisiensi yang baik.",
  ui_story_31380401_9_dialog_content = "Pergi ke bar juga oke. Aku bisa menyesap soda rasa buah sambil mendengarkan musik.",
  ui_story_31380401_10_dialog_content = "Bar selalu penuh sesak dengan berbagai macam orang. Kuharap tidak ada...",
  ui_story_31380401_11_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_31380401_12_dialog_content = "...?! Apa yang terjadi?",
  ui_story_31380401_13_dialog_content = "Sepertinya ada yang jatuh! Suaranya berasal dari bar!",
  ui_story_31380401_14_dialog_content = "Wah, kebetulan. Ayo kita lihat!",
  ui_story_31380401_15_dialog_content = "...!",
  ui_story_31380401_16_dialog_content = "<color=#e8d9bb>Di dalam Bar</color>",
  ui_story_31380401_17_dialog_content = "... lalu kucing itu melompat ke wajahku. Aku kehilangan keseimbangan lalu tersandung. Begitulah...",
  ui_story_31380401_18_dialog_content = "Korgon... kenapa bicaramu melantur?",
  ui_story_31380401_19_dialog_content = "Kau jatuh ke lantai karena kaki kirimu tersandung kaki kananmu?",
  ui_story_31380401_20_dialog_content = "Korgon! Kau baik-baik saja?",
  ui_story_31380401_21_dialog_content = "Oh... kau siapa? Matamu banyak sekali!",
  ui_story_31380401_22_dialog_content = "Selain itu, kenapa ada banyak anak kucing berlari berputar-putar di langit?",
  ui_story_31380401_23_dialog_content = "Napasmu bau alkohol... Kau mabuk, ya?",
  ui_story_31380401_24_dialog_content = "Alkohol? Oh... Aku memang meminumnya sedikit...",
  ui_story_31380401_25_dialog_content = "Tapi, itu semalam...",
  ui_story_31380401_26_dialog_content = "Bos dan yang lain bekerja keras.",
  ui_story_31380401_27_dialog_content = "Akhirnya kita selesai, tapi tak ada banyak waktu untuk menyisir bulu kucing kalau aku pulang sekarang.",
  ui_story_31380401_28_dialog_content = "Ya! Atasan yang memberi tugas tidak mempertimbangkan beban yang kita pikul.",
  ui_story_31380401_29_dialog_content = "Benar... Sebentar, kau siapa? Kenapa aku belum pernah melihatmu sebelumnya?",
  ui_story_31380401_30_dialog_content = "Aku hanya karyawan biasa yang juga dieksploitasi seperti dirimu.",
  ui_story_31380401_31_dialog_content = "Eh... Kau mau istirahat dulu?",
  ui_story_31380401_32_dialog_content = "Lingkaran hitam di bawah matamu besar sekali.",
  ui_story_31380401_33_dialog_content = "Aku bekerja lembur selama hampir dua puluh hari terakhir...",
  ui_story_31380401_34_dialog_content = "Hanya secangkir teh kesehatan panas dalam termos yang bisa mengobati rasa sakitku.",
  ui_story_31380401_35_dialog_content = "Kau juga mau? Ini bagus untuk menghilangkan kelelahan mental.",
  ui_story_31380401_36_dialog_content = "Benarkah seefektif itu? Kalau begitu, aku mau. Terima kasih.",
  ui_story_31380401_37_dialog_content = "Hmm? Kenapa aromanya aneh?",
  ui_story_31380401_38_dialog_content = "Yah, ini kan teh kesehatan. Ada banyak rempah di dalamnya.",
  ui_story_31380401_39_dialog_content = "Bahkan ada vitamin buatan Illumina juga, jadi teh ini benar-benar aman.",
  ui_story_31380401_40_dialog_content = "Baiklah, akan kucicipi.",
  ui_story_31380401_41_dialog_content = "Ahhh! Pedas sekali! Kenapa rasanya sangat pedas?!",
  ui_story_31380401_42_dialog_content = "Air! Aku butuh air!",
  ui_story_31380401_43_dialog_content = "Pedas? Sebentar, minumlah.",
  ui_story_31380401_44_dialog_content = "Glek, glek, glek... Ahhh...",
  ui_story_31380401_45_dialog_content = "Aku selamat! Terima kasih...",
  ui_story_31380401_46_dialog_content = "Kenapa air ini juga terasa agak aneh...? Hoek.",
  ui_story_31380401_47_dialog_content = "Eh?! A-ada apa?",
  ui_story_31380401_48_dialog_content = "Ini... Gawat! Aku mengambil cangkir yang salah!",
  ui_story_31380401_49_dialog_content = "Cangkir ini berisi minuman keras sulingan 96% spesial yang dibuat di Northland...",
  ui_story_31380401_50_dialog_content = "Aku sih tidak apa-apa saat meneguknya...",
  ui_story_31380401_51_dialog_content = "Yah... begitulah kejadiannya. Aku sudah lupa seperti apa orangnya... Hoek!",
  ui_story_31380401_52_dialog_content = "Oh, aku mau... tidur siang...",
  ui_story_31380401_53_dialog_content = "Korgon tertidur...",
  ui_story_31380401_54_dialog_content = "Biarkan saja dia tidur di sini sampai mabuknya hilang.",
  ui_story_31380401_55_dialog_content = "Tapi, ada orang yang tahan menenggak minuman keras sulingan seperti layaknya air biasa... Keadaannya akan lebih buruk kalau kita tidak bertindak.",
  ui_story_31380401_56_dialog_content = "Mungkin sebaiknya kita cari orangnya dan mengajaknya bicara secara langsung. Setidaknya agar tak ada korban lain seperti Korgon.",
  ui_story_31380401_57_dialog_content = "Aku setuju...",
  ui_story_31380401_58_dialog_content = "Korgon tidak menyebutkan ciri-ciri orang itu. Kira-kira siapa, ya?",
  ui_story_31380401_59_dialog_content = "...",
  ui_story_31380401_60_dialog_content = "Siobhan, kenapa raut mukamu aneh?",
  ui_story_31380401_61_dialog_content = "...! Tidak, t-tidak apa-apa, kok.",
  ui_story_31380401_62_dialog_content = "Aku hanya menganalisis beberapa kemungkinannya. Mau dengar?",
  ui_story_31380401_63_dialog_content = "Siobhan, apa yang terpikir olehmu?",
  ui_story_31380401_64_dialog_content = "...! B-benar. Aku memikirkan beberapa kemungkinan.",
  ui_story_31380401_65_dialog_content = "Coba jelaskan.",
  ui_story_31380401_66_dialog_content = "Yah... pertama, orang itu kuat minum-minum. Jadi, dia pasti sering pergi ke bar.",
  ui_story_31380401_67_dialog_content = "Kedua, Korgon tidak mengenali orang itu. Jadi, orangnya pasti berasal dari faksi yang jarang berurusan dengannya.",
  ui_story_31380401_68_dialog_content = "Terakhir, orang itu merekomendasikan cara yang sangat unik untuk menambahkan saus cabai ke barbeku.",
  ui_story_31380401_69_dialog_content = "Kesimpulannya, kurasa kita harus mulai menyelidiki anggota Rediesel Wrench dulu.",
  ui_story_31380401_70_dialog_content = "Kau memang peneliti yang bisa diandalkan. Sekarang semuanya sudah jelas!",
  ui_story_31380401_71_dialog_content = "Kalau begitu, ayo kita minta keterangan dari para anggota Rediesel Wrench.",
  ui_story_31380401_72_dialog_content = "Benar, ayo.",
  ui_story_31380401_73_dialog_content = "Fyuh...",
  ui_story_31380401_74_dialog_content = "<color=#e8d9bb>Kamar Sinsa</color>",
  ui_story_31380401_75_dialog_content = "Kau mau tahu apa aku pergi ke bar kemarin?",
  ui_story_31380401_76_dialog_content = "Tentu saja tidak!",
  ui_story_31380401_77_dialog_content = "Kalau begitu, kau pergi ke mana? Apa ada yang bisa membuktikannya?",
  ui_story_31380401_78_dialog_content = "Wah, kau terdengar sangat arogan, ya?",
  ui_story_31380401_79_dialog_content = "Aku pergi ke mana pun semauku!",
  ui_story_31380401_80_dialog_content = "Apa hubungannya denganmu?",
  ui_story_31380401_81_dialog_content = "T-tidak, bukan begitu maksud kami.",
  ui_story_31380401_82_dialog_content = "Hanya saja ada orang misterius yang membuat Korgon mabuk berat, dan aku berharap itu bukan kamu.",
  ui_story_31380401_83_dialog_content = "Cih. Baiklah. Karena semalam benar-benar membosankan, aku merampok beberapa orang dengan saudara-saudaraku.",
  ui_story_31380401_84_dialog_content = "Hah...?",
  ui_story_31380401_85_dialog_content = "Apa yang membuatmu terkejut?",
  ui_story_31380401_86_dialog_content = "Joanie Boom, Regina, dan yang lain pergi denganku. Jadi, silakan tanyai mereka kalau kau tidak percaya.",
  ui_story_31380401_87_dialog_content = "Kalau tidak salah, aku merampok karavan yang mengangkut barang ke Lumopolis.",
  ui_story_31380401_88_dialog_content = "Mereka sangat kaya! Perdagangan ini membuatku untung besar!",
  ui_story_31380401_89_dialog_content = "Anu, menurutku yang seperti itu tak bisa disebut \"perdagangan\"...",
  ui_story_31380401_90_dialog_content = "Aku sudah memberitahumu segalanya.",
  ui_story_31380401_91_dialog_content = "Sana, tanyakan saja kepada orang lain.",
  ui_story_31380401_92_dialog_content = "Aku paham...",
  ui_story_31380401_93_dialog_content = "Apa kau mengenal orang yang kuat minum-minum?",
  ui_story_31380401_94_dialog_content = "Oh, iya. Aku hampir lupa menanyakannya.",
  ui_story_31380401_95_dialog_content = "Orang yang kuat minum-minum? Ada banyak. Butuh waktu berhari-hari untuk menyelidiki mereka semua.",
  ui_story_31380401_96_dialog_content = "Katakan saja. Biar kami urus sisanya.",
  ui_story_31380401_97_dialog_content = "<color=#e8d9bb>Beberapa jam kemudian...</color>",
  ui_story_31380401_98_dialog_content = "Tentu saja aku berolahraga tadi malam.",
  ui_story_31380401_99_dialog_content = "Aku harus terus berlatih agar bisa menjadi salah satu anggota terbaik di Rediesel Wrench.",
  ui_story_31380401_100_dialog_content = "Aku? Bos bikin kacau mobilnya lagi... Aku sudah habiskan semua waktuku untuk memperbaikinya dari tadi malam sampai pagi ini.",
  ui_story_31380401_101_dialog_content = "Pertanyaanmu sangat aneh.",
  ui_story_31380401_102_dialog_content = "Wah, sudah larut malam. Aku sangat lelah... Vice, berapa orang yang sudah kita tanyai?",
  ui_story_31380401_103_dialog_content = "Totalnya 12, termasuk Fleur.",
  ui_story_31380401_104_dialog_content = "Berapa sisanya?",
  ui_story_31380401_105_dialog_content = "Masih ada... 26 orang.",
  ui_story_31380401_106_dialog_content = "... Kenapa mereka semua kuat minum-minum?!",
  ui_story_31380401_107_dialog_content = "Kita tak bisa terus-terusan menyelidikinya...",
  ui_story_31380401_108_dialog_content = "Caelestite, bagaimana kalau kita lupakan saja insiden ini untuk sekarang?",
  ui_story_31380401_109_dialog_content = "Sejauh ini korbannya hanya Korgon, dan tak ada kerugian besar yang ditimbulkan.",
  ui_story_31380401_110_dialog_content = "Kurasa sebaiknya kita memasang pemberitahuan di bar untuk memperingatkan semua orang. Itu akan lebih efektif dan efisien ketimbang penyelidikan tanpa arah.",
  ui_story_31380401_111_option_content = "Sepertinya... kau benar.",
  ui_story_31380401_112_dialog_content = "Kita hanya akan kelelahan kalau seperti ini.",
  ui_story_31380401_113_dialog_content = "Benar...",
  ui_story_31380401_114_option_content = "Ayo kita lakukan. Aku tak mau menyelidiki ini lagi...",
  ui_story_31380401_115_dialog_content = "Beristirahatlah dulu...",
  ui_story_31380401_116_dialog_content = "Ayo kita lakukan. Malam ini kita beristirahat dulu lalu mempertimbangkan untuk memasang pemberitahuan besok...",
  ui_story_31380401_117_dialog_content = "Oh! Ada Sio si peneliti superlangka rupanya!",
  ui_story_31380401_118_dialog_content = "Kenapa kau kemari...?!",
  ui_story_31380401_119_dialog_content = "Yah, aku melihatmu mencari obat penenang di bar tadi malam, jadi kupikir kau terlalu banyak minum!",
  ui_story_31380401_120_dialog_content = "Tapi, kau justru sangat energik hari ini!",
  ui_story_31380401_121_dialog_content = "Kau memang kebal terhadap efek alkohol, Sio!",
  ui_story_31380401_122_dialog_content = "Hah...?!",
  ui_story_31380401_123_dialog_content = "T-tolong jangan mengada-ada...!",
  ui_story_31380401_124_dialog_content = "Tadi malam, di bar, mencari obat penenang...?",
  ui_story_31380401_125_dialog_content = "Dengar...",
  ui_story_31380401_X125_dialog_content = "Dan kau kebal terhadap efek alkohol?!",
  ui_story_31380401_126_dialog_content = "Jadi, kau pelakunya?!",
  ui_story_31380401_127_dialog_content = "Kami memercayaimu dan mengikutimu seharian untuk meminta keterangan.",
  ui_story_31380401_128_dialog_content = "Bu Siobhan, yang tampak sangat dewasa dan bisa diandalkan sebenarnya...",
  ui_story_31380401_129_dialog_content = "Dasar pembohong besar!",
  ui_story_31380401_130_dialog_content = "Ini bukan masalah besar, tahu?",
  ui_story_31380401_131_dialog_content = "Kuakui aku memang tidak menanganinya dengan baik.",
  ui_story_31380401_132_dialog_content = "Hampir seharian ini aku mencari obat penenang, tapi hasilnya nihil. Dan masih saja ketahuan...",
  ui_story_31380401_133_dialog_content = "Aku bersedia melakukan apa pun untuk mengganti kerugian yang kutimbulkan.",
  ui_story_31380401_134_dialog_content = "Aku juga akan bicara dengan Korgon.",
  ui_story_31380401_135_dialog_content = "Kalau harus minta maaf atau membayar kompensasi, aku tak akan menghindar jika itu memang kewajibanku,",
  ui_story_31380401_136_dialog_content = "Inilah pedoman yang kupegang dalam pekerjaan dan kehidupan.",
  ui_story_31380401_137_dialog_content = "Hah... sudahlah. Memang tidak ada kerugian besar. Tapi, jangan lupa meminta maaf pada Korgon.",
  ui_story_31380401_138_dialog_content = "Benar. Jadi, kau tak perlu pasang raut muka serius begitu, Sio.",
  ui_story_31380401_139_dialog_content = "Jangan sedih! Aku baru saja mau memperlihatkan teknologi kuno yang kutemukan.",
  ui_story_31380401_140_dialog_content = "Benarkah? Coba lihat!",
  ui_story_31380401_141_dialog_content = "Oh! Ini benda bersejarah!",
  ui_story_31380401_142_dialog_content = "Menurut perkiraanku, perangkat ini berisi data ilmiah dan teknologi kuno, dan membutuhkan alat khusus untuk memecahkan kodenya...",
  ui_story_31380401_143_dialog_content = "Mata yang bagus, Sio! Kau mengerti dengan cuma satu pandangan!",
  ui_story_31380401_144_dialog_content = "Memangnya benda apa ini?",
  ui_story_31380401_145_dialog_content = "Ini perangkat yang berisi video game kuno!",
  ui_story_31380401_146_dialog_content = "...!?",
  ui_story_31380401_147_dialog_content = "Silakan menganalisisnya, Sio. Aku tahu itu keahlianmu.",
  ui_story_31380401_148_dialog_content = "Jangan lupa menyelesaikan game-nya dalam tiga hari, lalu buat ulasannya. Nah, aku pergi dulu, ya. Sampai jumpa!",
  ui_story_31380401_149_dialog_content = "...",
  ui_story_31380401_150_dialog_content = "Misi ini benar-benar... Profesor Siobhan?!",
  ui_story_31380401_151_dialog_content = "PlayerName! Bu Siobhan pingsan!",
  ui_story_31380401_152_dialog_content = "Siobhan? Siobhan!!!",
  ui_story_31380601_1_dialog_content = "Berkat bantuanmu kami dapat menyelesaikan misi hari ini dengan lancar.",
  ui_story_31380601_2_dialog_content = "Tidak berarti. Saya hampir tidak mengangkat jari.",
  ui_story_31380601_3_dialog_content = "Bagaimana kalau kita pergi minum setelah aku melapor ke Petugas Gronru?",
  ui_story_31380601_4_dialog_content = "Aku tidak tahu soal itu...",
  ui_story_31380601_5_dialog_content = "Anda tersipu sekarang karena Anda pikir saya baru saja mengajak Anda berkencan, bukan? Ah, menjadi muda dan lugu lagi...",
  ui_story_31380601_6_dialog_content = "Jika wajahku berubah warna barusan, itu lebih mungkin karena takut daripada malu.",
  ui_story_31380601_7_dialog_content = "Lagi pula, semua orang tahu Anda bahkan dapat meminum minuman keras suling 96% khusus Northland seperti airnya.",
  ui_story_31380601_8_dialog_content = "Nah, itu berlebihan... Saya hanya suka sedikit penurunan sesekali untuk membawa saya ke tempat bahagia saya.",
  ui_story_31380601_9_dialog_content = "\"Sedikit tetes\" mungkin meremehkan abad ini...",
  ui_story_31380601_10_dialog_content = "Bagaimana kalau kita ambil secangkir kopi hitam saja?",
  ui_story_31380601_11_dialog_content = "Kopi, teh, jus... Aku baik-baik saja dengan semua itu.",
  ui_story_31380601_12_dialog_content = "Ini kencan, kalau begitu.",
  ui_story_31380601_13_dialog_content = "Hah? Itu...",
  ui_story_31380601_14_dialog_content = "Itu Liliam. Mereka baru saja keluar dari kantor Petugas Gronru.",
  ui_story_31380601_15_dialog_content = "Mereka berpakaian berbeda dari biasanya.",
  ui_story_31380601_16_dialog_content = "Mungkin karena konser yang akan datang.",
  ui_story_31380601_17_dialog_content = "Aku tahu kamu akan melakukannya dengan baik. Buat Lab Riset bangga!",
  ui_story_31380601_18_dialog_content = "Perintah diakui. Lilliam No. 1 ingin mendapatkan prestise untuk Lab Riset.",
  ui_story_31380601_19_dialog_content = "Menerjemahkan dan mengubah: Lilliam No. 1 akan menempati salah satu dari tiga tempat pertama dalam audisi konser.",
  ui_story_31380601_20_dialog_content = "Dan No. 2 juga akan masuk ke tiga besar!",
  ui_story_31380601_21_dialog_content = "No. 2 telah menyiapkan gaya idola baru, hanya untuk konser ini~ Langsung mengarah ke hatimu!☆",
  ui_story_31380601_22_dialog_content = "No 2, ada apa dengan matamu? Apakah kamu baik - baik saja?",
  ui_story_31380601_23_dialog_content = "Aku mengedipkan mata! Semua orang tahu bahwa kedipan mata dapat menyampaikan bahasa bisu yang misterius dari pesona seorang idola.❤",
  ui_story_31380601_24_dialog_content = "Peringatan! Petugas Gronru mengalami kejang wajah.",
  ui_story_31380601_25_dialog_content = "Menerjemahkan dan mengubah: Sudut mulut Petugas Gronru berkedut.",
  ui_story_31380601_26_dialog_content = "Berhipotesis... Petugas Gronru tidak dapat memahami arti dari kedipan mata No.2.",
  ui_story_31380601_27_dialog_content = "Baiklah, Anda harus pergi dan mendaftar. Pastikan Anda mempersiapkan diri dengan baik.",
  ui_story_31380601_28_dialog_content = "Perintah diakui. Program diluncurkan... Mendaftar.",
  ui_story_31380601_29_dialog_content = "Petugas Gronru, saya di sini untuk melaporkan misi.",
  ui_story_31380601_30_dialog_content = "Ini peneliti super langka saya, Sio! Anda kembali tepat pada waktunya!",
  ui_story_31380601_31_dialog_content = "Tentang misi ini—saya mengerjakannya bersama PlayerName...",
  ui_story_31380601_32_dialog_content = "Jangan katakan lagi. Saya telah membaca laporan tertulis Anda dan itu baik-baik saja.",
  ui_story_31380601_33_dialog_content = "Sekarang setelah kita semua selesai bekerja, mengapa kita tidak bermain game! Ya!",
  ui_story_31380601_34_dialog_content = "G-Gaming? erm...",
  ui_story_31380601_35_dialog_content = "(Uh-oh, saya pikir dia baru saja memicu gameofobia Siobhan lagi.)",
  ui_story_31380601_36_dialog_content = "Mari kita bermain di lain hari. Siobhan masih memiliki beberapa hal lain yang harus dilakukan hari ini.",
  ui_story_31380601_37_dialog_content = "Itu tidak benar, Anda tidak memiliki misi lain untuk dilakukan, bukan?",
  ui_story_31380601_38_dialog_content = "Atau... apakah kamu ikut serta dalam audisi konser juga!?",
  ui_story_31380601_39_dialog_content = "Hah!? Yah um, ya, saya baru saja akan mendaftar.",
  ui_story_31380601_40_dialog_content = "Jika itu masalahnya, saya rasa itulah akhirnya!",
  ui_story_31380601_41_dialog_content = "Ayo daftar. Saya kira saya hanya memiliki Anda untuk bermain game sekarang, PlayerName.",
  ui_story_31380601_42_dialog_content = "Sebenarnya, saya baru ingat bahwa saya memiliki sesuatu yang harus saya lakukan sekarang juga!",
  ui_story_31380601_43_dialog_content = "Jangan bilang kamu mau daftar juga!?",
  ui_story_31380601_44_dialog_content = "Erm, aku pasti tidak mendaftar, tapi ini berhubungan dengan persiapan konser.",
  ui_story_31380601_45_dialog_content = "Anda harus menjadi bagian dari kru sponsor konser itu. Bisakah kamu menjaga Siobhan dan Lilliam secara khusus untukku?",
  ui_story_31380601_46_dialog_content = "Apakah Anda meminta bantuan pribadi sekarang?",
  ui_story_31380601_47_dialog_content = "Tidak, tapi jika Siobhan atau Lilliam menang, Research Lab akan mendapat dana khusus.",
  ui_story_31380601_48_dialog_content = "Dan dengan dana, saya bisa mengembangkan game idola saya sendiri! Ha ha ha!",
  ui_story_31380601_49_dialog_content = "Bukankah itu termasuk penyalahgunaan dana publik!?",
  ui_story_31380601_50_dialog_content = "Baiklah, aku akan meninggalkan kalian untuk itu kemudian!",
  ui_story_31380601_51_dialog_content = "Fiuh... Anda benar-benar membantu saya keluar dari situasi sulit!",
  ui_story_31380601_52_dialog_content = "Jangan sebutkan itu. Saya juga membantu diri saya keluar dari kekacauan itu.",
  ui_story_31380601_53_dialog_content = "Aku tahu kita harus pergi minum itu sekarang, tapi aku benar-benar punya sesuatu untuk diurus.",
  ui_story_31380601_54_dialog_content = "Maaf... Aku akan mengundangmu lain kali, oke?",
  ui_story_31380601_55_dialog_content = "Tentu, tidak masalah... Tapi apa yang tiba-tiba perlu Anda urus?",
  ui_story_31380601_56_dialog_content = "Saya akan mendaftar untuk konser sekarang.",
  ui_story_31380601_57_dialog_content = "Hah? Anda tidak hanya menggunakannya sebagai alasan yang nyaman?",
  ui_story_31380601_58_dialog_content = "Saya benar-benar tidak ada pekerjaan yang harus dilakukan saat ini, jadi mengapa tidak memanfaatkan kesempatan ini untuk mengalami sesuatu yang baru?",
  ui_story_31380601_59_dialog_content = "Tentu saja, itu juga untuk mencegah seseorang memaksaku bermain-main dengannya.",
  ui_story_31380601_60_dialog_content = "Masalahnya, saya belum pernah mengambil bagian dalam hal semacam ini sebelumnya. Saya merasa gugup.",
  ui_story_31380601_61_dialog_content = "Bisakah Anda datang dan menemukan saya nanti?",
  ui_story_31380601_62_dialog_content = "Tentu, bukan masalah.",
  ui_story_31380601_63_dialog_content = "Siobhan memintaku pergi ke belakang panggung untuk menemukannya... Aku bertanya-tanya bagaimana persiapannya.",
  ui_story_31380601_64_dialog_content = "Apakah ini? Pintunya terbuka—",
  ui_story_31380601_65_dialog_content = "Hah?",
  ui_story_31380601_66_dialog_content = "PlayerName, Anda datang.",
  ui_story_31380601_67_dialog_content = "Ah... S-Siobhan?",
  ui_story_31380601_68_dialog_content = "Apa masalahnya? Tidakkah menurutmu aku terlihat luar biasa?",
  ui_story_31380601_69_dialog_content = "Kamu terlihat begitu cantik sehingga sesaat di sana aku merasa jiwaku meninggalkanku.",
  ui_story_31380601_70_dialog_content = "Betulkah? Terima kasih!",
  ui_story_31380601_71_dialog_content = "Selama Anda berpikir saya terlihat baik, saya tahu saya tidak perlu khawatir.",
  ui_story_31380601_72_dialog_content = "Tapi bukan berarti saya bisa berpuas diri.",
  ui_story_31380601_73_dialog_content = "Saya meminta Anda untuk datang karena saya berharap Anda dapat memberikan analisis jujur Anda dari sudut pandang yang rasional, netral, dan objektif.",
  ui_story_31380601_74_dialog_content = "Analisis? Ini hanya kontes menyanyi, untuk menangis dengan suara keras!",
  ui_story_31380601_75_dialog_content = "Sebagai seorang akademisi yang serius, saya perlu menyalurkan semangat penelitian bahkan ketika mengikuti kompetisi menyanyi.",
  ui_story_31380601_76_dialog_content = "Saya bahkan menulis tesis untuk kompetisi ini.",
  ui_story_31380601_77_dialog_content = "Ini adalah analisis dari berbagai faktor yang mempengaruhi hasil kompetisi—mulai dari panggung hingga sistem kompetisi, peserta, dan aspek lainnya.",
  ui_story_31380601_78_dialog_content = "Mari kita mulai dengan panggung—",
  ui_story_31380601_79_dialog_content = "Ini adalah panggung terbuka, jadi penampilan akan sangat dipengaruhi oleh cuaca.",
  ui_story_31380601_80_dialog_content = "Jika berangin atau hujan, itu akan meredam performa.",
  ui_story_31380601_81_dialog_content = "Oleh karena itu, selama pertunjukan, kita harus benar-benar mempertimbangkan dampak potensial dari berbagai kondisi cuaca.",
  ui_story_31380601_82_dialog_content = "Selanjutnya, mari kita bicara tentang sistem kompetisi—",
  ui_story_31380601_83_dialog_content = "Hal pertama yang harus diperhatikan adalah audisi itu sendiri, yang bisa dikatakan sebagai fase tersulit.",
  ui_story_31380601_84_dialog_content = "Jika satu kesalahan dibuat selama fase ini, peserta akan menghadapi eliminasi, dan tidak akan mendapat kesempatan lagi untuk terus mengambil bagian.",
  ui_story_31380601_85_dialog_content = "Selain itu, banyak dari peserta telah mengumpulkan tingkat popularitas tertentu dan basis penggemar yang cukup besar sebelum dimulainya kompetisi.",
  ui_story_31380601_86_dialog_content = "Mereka akan menikmati keuntungan yang lebih besar dalam persaingan.",
  ui_story_31380601_87_dialog_content = "Jadi, yang terpenting di sini adalah menganalisis para peserta!",
  ui_story_31380601_88_dialog_content = "Tabel ini menunjukkan \"analisis peringkat idola\" untuk lawan saya dan saya sendiri.",
  ui_story_31380601_89_dialog_content = "Ini termasuk menyanyi, menari, penampilan, figur, EQ, dan IQ, dengan skor maksimal 5 untuk setiap kategori.",
  ui_story_31380601_90_dialog_content = "Charon—",
  ui_story_31380601_91_dialog_content = "Menyanyi—5, menari—5, penampilan—4, figur—4, EQ—0, IQ—3.",
  ui_story_31380601_92_dialog_content = "Kandidat populer untuk menempati posisi teratas kompetisi ini.",
  ui_story_31380601_93_dialog_content = "Logam gothic mengaduk hati seperti gelombang yang mengamuk.",
  ui_story_31380601_94_dialog_content = "Dia memiliki cukup keunggulan untuk menakuti lawan-lawannya.",
  ui_story_31380601_95_dialog_content = "Kelemahannya adalah EQ-nya yang rendah tidak akan membawanya jauh.",
  ui_story_31380601_96_dialog_content = "Lilliam—",
  ui_story_31380601_97_dialog_content = "Menyanyi: 2, menari: 2, penampilan: 4, angka: 3, EQ: 1, IQ: 5.",
  ui_story_31380601_98_dialog_content = "Sebuah produk dari generasi baru, mereka memiliki kebaruan tertentu karena bertentangan dengan logika konvensional.",
  ui_story_31380601_99_dialog_content = "Kemuliaan dan martabat empat orang (mesin) mempertaruhkan semuanya untuk membangkitkan tubuh utama mereka...",
  ui_story_31380601_100_dialog_content = "Kelemahan mereka adalah mereka terlalu robotik.",
  ui_story_31380601_101_dialog_content = "Meskipun beberapa orang tergila-gila dengan pesaing semacam ini, mereka tidak memiliki apa yang diperlukan untuk memenangkan hati masyarakat umum.",
  ui_story_31380601_102_dialog_content = "Analisis Anda sangat rinci... Saya tidak pernah menyangka Anda baru dalam hal semacam ini.",
  ui_story_31380601_103_dialog_content = "Jangan lupa, saya seorang peneliti profesional!",
  ui_story_31380601_104_dialog_content = "Tapi dari mana Anda mendapatkan semua informasi tentang pesaing Anda?",
  ui_story_31380601_105_dialog_content = "Ya, saya mengundang staf pendaftaran untuk minum-minum.",
  ui_story_31380601_106_dialog_content = "Mereka akhirnya menceritakan semuanya padaku. Bahkan saya terkejut dengan banyaknya info yang mereka berikan kepada saya.",
  ui_story_31380601_107_dialog_content = "Aku tidak berencana menyelidiki ini secara menyeluruh...",
  ui_story_31380601_108_dialog_content = "Apakah Anda memberi mereka sedikit minuman favorit Anda untuk mengendurkan bibir mereka?",
  ui_story_31380601_109_dialog_content = "Yah, aku tidak mencampuri urusan pribadi. Saya hanya mencatat informasi yang berkaitan dengan kompetisi.",
  ui_story_31380601_110_dialog_content = "Untung kaulah yang menemukan semua ini. Jika orang lain mendapatkan informasi ini, itu bisa menjadi berita buruk bagi peserta lain.",
  ui_story_31380601_111_dialog_content = "Sudahlah tentang itu—mari kita lanjutkan memeriksa data pesaing.",
  ui_story_31380601_112_dialog_content = "Saya baru saja memperkenalkan banyak pesaing kepada Anda, tetapi yang paling tangguh adalah sebagai berikut—",
  ui_story_31380601_113_dialog_content = "Prajurit terakhir dan terkuat dari Keluarga Sakura!",
  ui_story_31380601_114_dialog_content = "Hiiro!",
  ui_story_31380601_115_dialog_content = "Peringkat spesifiknya tidak dapat dihitung sekarang, tetapi Anda dapat yakin bahwa statistiknya tidak sesuai dengan grafik.",
  ui_story_31380601_116_dialog_content = "Pemenang kompetisi tahun lalu, Hiiro, adalah lawan yang sangat kuat.",
  ui_story_31380601_117_dialog_content = "Seindah bunga sakura yang mengambang, dan seganas naga yang mengaum.",
  ui_story_31380601_118_dialog_content = "Saya tidak yakin apakah ada Aurorian hidup yang bisa mengalahkannya.",
  ui_story_31380601_119_dialog_content = "Saya tidak pernah menyadari bahwa Hiiro sangat mengesankan!",
  ui_story_31380601_120_dialog_content = "Jadi apa yang akan kamu lakukan? Apakah Anda akan mencoba untuk mengalahkan Hiiro?",
  ui_story_31380601_121_dialog_content = "Yah, bagiku, Siobhan—",
  ui_story_31380601_122_dialog_content = "Menyanyi: 1, menari: 1, penampilan: 6, angka: 6, EQ: 5, IQ: 5.",
  ui_story_31380601_123_dialog_content = "Tunggu. Anda memberikan penampilan dan angka masing-masing 6 poin?",
  ui_story_31380601_124_dialog_content = "Saya pikir Anda mengatakan maksimal lima poin!",
  ui_story_31380601_125_dialog_content = "*Uhuk* Meskipun aku tidak pandai menyanyi atau menari, empat area lainnya harus mengimbanginya.",
  ui_story_31380601_126_dialog_content = "Apa kau berpura-pura tidak mendengarku?",
  ui_story_31380601_127_dialog_content = "Sudahlah, kedua skor itu objektif.",
  ui_story_31380601_128_dialog_content = "Hah!",
  ui_story_31380601_129_dialog_content = "Apakah kamu tertawa?",
  ui_story_31380601_130_dialog_content = "Anyways... jika saya memberikan segalanya, saya akan memiliki kesempatan untuk memenangkan semua ini.",
  ui_story_31380601_131_dialog_content = "Tapi kamu terlalu memaksakan diri di kategori menyanyi dan menari... Kamu hanya memberi satu poin untuk masing-masing?",
  ui_story_31380601_132_dialog_content = "Apakah Anda pikir Anda telah mempersiapkan diri dengan cukup baik untuk masuk ke tiga besar?",
  ui_story_31380601_133_dialog_content = "Itulah alasan lain saya mengundang Anda ke sini. Tidak mungkin penilaian saya tentang diri saya bisa cukup objektif.",
  ui_story_31380601_134_dialog_content = "Mengapa Anda tidak menunjukkan kepada saya bagian dari kinerja Anda dan biarkan saya memberi Anda skor?",
  ui_story_31380601_135_dialog_content = "Anda ingin saya tampil sekarang? Ini sangat mendadak... Sejujurnya, aku merasa sedikit malu.",
  ui_story_31380601_136_dialog_content = "Tapi jika itu yang kau inginkan...",
  ui_story_31380601_137_dialog_content = "Oke, mari kita lakukan ini.",
  ui_story_31380601_138_dialog_content = "(Hmm... Aku tahu ini hanya pembukaan penampilannya, tapi gaya Siobhan tidak buruk sama sekali.)",
  ui_story_31380601_139_dialog_content = "(Langkah ringan, postur tubuh yang indah, wajah yang cantik—dia memiliki peluang bagus untuk memikat sebagian besar penonton.)",
  ui_story_31380601_140_dialog_content = "♪ Pergi bekerja saat aku bangun, tidak punya waktu untuk makan ♪",
  ui_story_31380601_141_dialog_content = "♪ Terlalu banyak pekerjaan yang harus ditangani, tidak punya waktu untuk tidur ♪",
  ui_story_31380601_142_dialog_content = "Tunggu, lagu macam apa ini!?",
  ui_story_31380601_143_dialog_content = "Saya memilih lagu rap acak dari tangga lagu teratas sebelumnya.",
  ui_story_31380601_144_dialog_content = "Saya pikir itu semacam logam berat ...",
  ui_story_31380601_145_dialog_content = "Menilai dari ekspresimu, kurasa aku tidak sebaik dulu.",
  ui_story_31380601_146_dialog_content = "Anda pernah tampil di atas panggung sebelumnya?",
  ui_story_31380601_147_dialog_content = "Ketika saya masih sangat muda dan tinggal di Undercity 66, saya menari di beberapa pertunjukan grup.",
  ui_story_31380601_148_dialog_content = "Ketika Anda masih sangat muda !?",
  ui_story_31380601_149_dialog_content = "Saya baru berusia empat atau lima tahun tetapi saya masih memimpin rombongan.",
  ui_story_31380601_150_dialog_content = "Saya rasa saya bisa mencetak setidaknya empat dalam menyanyi dan menari saat itu.",
  ui_story_31380601_151_dialog_content = "Tapi, mengingat fakta bahwa saya tidak berlatih selama bertahun-tahun, saya berasumsi bahwa keterampilan saya akan menurun secara signifikan, jadi saya memberikan skor objektif satu poin.",
  ui_story_31380601_152_dialog_content = "Penilaian Anda terhadap diri sendiri sebenarnya sangat rasional, netral, dan objektif.",
  ui_story_31380601_153_dialog_content = "Sekarang sepertinya akan sulit untuk menang hanya dengan menyanyi dan menari.",
  ui_story_31380601_154_dialog_content = "Jadi, menurut Anda apakah saya harus menambahkan beberapa bakat pribadi saya ke lagu dan tarian saya?",
  ui_story_31380601_155_dialog_content = "Bakat pribadi seperti apa?",
  ui_story_31380601_156_dialog_content = "Pembongkaran-",
  ui_story_31380601_157_dialog_content = "Aku akan membuat bom asap kecil yang mengeluarkan ledakan dahsyat...",
  ui_story_31380601_158_dialog_content = "Kemudian saya akan keluar dari asap, memberikan kejutan kecil yang menyenangkan kepada penonton.",
  ui_story_31380601_159_dialog_content = "(Saya tidak tahu apakah panggung bisa menahan ledakan... Jika runtuh, itu pasti akan menjadi kejutan.)",
  ui_story_31380601_160_dialog_content = "Kamuflase Tingkat Lanjut—",
  ui_story_31380601_161_dialog_content = "Saya akan bersembunyi di antara dekorasi dan terus meneriakkan, \"Siobhan yang terbaik,\" untuk mencuci otak orang yang lewat.",
  ui_story_31380601_162_dialog_content = "(Apakah semudah itu mencuci otak orang?)",
  ui_story_31380601_163_dialog_content = "Tarian Laba-laba—",
  ui_story_31380601_164_dialog_content = "Saya akan membuat jaring laba-laba saya yang menggemaskan melintasi panggung, dan setiap laba-laba kecil akan memantul mengikuti musik.",
  ui_story_31380601_165_dialog_content = "Mereka juga dapat berkeliaran ke penonton untuk berinteraksi dengan orang-orang. Semua orang akan menyukainya, bukan?",
  ui_story_31380601_166_dialog_content = "(Dan jika seorang penonton menderita arachnophobia, mereka akan pingsan di tempat...)",
  ui_story_31380601_167_dialog_content = "Dan yang terakhir adalah Precision Dusting.",
  ui_story_31380601_168_dialog_content = "Jika semuanya gagal, saya masih memiliki kartu as ini di lengan baju saya!",
  ui_story_31380601_169_dialog_content = "Saya telah menghilangkan debu dari barang antik selama bertahun-tahun sekarang, dan telah menguasai keterampilan unik membersihkan debu.",
  ui_story_31380601_170_dialog_content = "Jika saya membersihkan seluruh penonton, mereka akan senang dengan saya, bukan?",
  ui_story_31380601_171_dialog_content = "(Ketika Anda tiba-tiba mulai menyerang ruang pribadi semua orang dengan kemoceng Anda, siapa yang akan senang dengan itu!?)",
  ui_story_31380601_172_dialog_content = "Aku jadi bingung! Keterampilan apa yang harus saya gunakan?",
  ui_story_31380601_173_dialog_content = "PlayerName, dapatkah Anda membantu saya memilih salah satu?",
  ui_story_31380601_174_option_content = "Bisakah saya memilih tidak satupun dari mereka?",
  ui_story_31380601_175_dialog_content = "Apakah mereka benar-benar tidak cocok untuk kompetisi?",
  ui_story_31380601_176_dialog_content = "(Kepala Siobhan menggantung sangat rendah... Dia terlihat sangat putus asa.)",
  ui_story_31380601_177_dialog_content = "Keahlianmu bagus, tapi tidak cocok untuk pertunjukan seperti ini.",
  ui_story_31380601_178_dialog_content = "Terima kasih atas keterusteranganmu... dan atas kebaikanmu.",
  ui_story_31380601_179_option_content = "Pilih saja yang Anda suka!",
  ui_story_31380601_180_dialog_content = "Anda pikir mereka semua baik, kan ...? Jadi, sulit menentukan pilihan...?",
  ui_story_31380601_181_dialog_content = "Kemudian saya akan menggunakan semuanya untuk memaksimalkan peluang saya untuk menang.",
  ui_story_31380601_182_dialog_content = "(Saya harap tidak ada hal buruk yang terjadi dari ini.)",
  ui_story_31380601_183_dialog_content = "Aku benar-benar membuatmu melalui banyak hal hari ini.",
  ui_story_31380601_184_dialog_content = "Tidak apa-apa. Saya benar-benar mendapatkan banyak wawasan hari ini ...",
  ui_story_31380601_185_dialog_content = "Sekarang, saya akan berusaha sekuat tenaga untuk mempersiapkan audisi saya!",
  ui_story_31380601_186_dialog_content = "Semoga berhasil!"
}
return config
